contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 witnessSalt) public payable {
        require(witnessSalt != 0);

        address witness = address(uint160(witnessSalt % type(uint160).max) + 1);
        require(witness != address(this));

        uint256 witnessBefore = c.balances(witness); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 witnessAfter = c.balances(witness); if (__ESBMC_reverted()) return;

        assert(witnessAfter == witnessBefore);
    }

    receive() external payable {}
}

