pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 witnessSalt) internal {
        vm.assume(witnessSalt != 0);
        address witness = address(uint160(witnessSalt % type(uint160).max) + 1);
        vm.assume(witness != address(this));
        uint256 witnessBefore;
        try c.balances(witness) returns (uint256 __r) { witnessBefore = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        uint256 witnessAfter;
        try c.balances(witness) returns (uint256 __r) { witnessAfter = __r; } catch { return; }
        assertTrue(witnessAfter == witnessBefore);
    }

    function testFuzz_run(uint256 witnessSalt) public {
        _run(witnessSalt);
    }

    receive() external payable {}
